520	/**
521	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
522	 * passada, período anterior do filtro…). Retorna null quando a base é
523	 * ausente ou não positiva — sem base honesta, sem número inventado.
524	 */
525	export function relativeDelta(
526	  current: number,
527	  base: number | null | undefined,
528	): number | null {
529	  if (base == null || base <= 0) return null;
530	  return ((current - base) / base) * 100;
531	}
532	
533	/**
534	 * Delta % vs MESMO DIA da semana anterior — caso particular de
535	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
536	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
537	 */
538	export function weekOverWeekDelta(
539	  current: number,
540	  lastWeek: number | null | undefined,
541	): number | null {
542	  return relativeDelta(current, lastWeek);
543	}
544	
545	/**
546	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
547	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
548	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
549	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
550	 * usada no pró-rata da meta, por consistência).
551	 *
552	 * Comparar dia parcial com dia completo inflava a queda de manhã.
553	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
554	 *
555	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
556	 * (fração 0 — não há ponto de comparação honesto).
557	 */
558	export function proRataDayBase(
559	  referenceDayTotal: number | null | undefined,
560	  now: Date,
561	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
562	): number | null {
563	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
564	  const fraction = businessDayFraction(now, hours);
565	  if (fraction <= 0) return null;
566	  return referenceDayTotal * fraction;
567	}
568	
569	/**
570	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
571	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
572	 * a API existente).
573	 */
574	export function proRataLastWeekBase(
575	  lastWeek: number | null | undefined,
576	  now: Date,
577	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
578	): number | null {
579	  return proRataDayBase(lastWeek, now, hours);
580	}
