690	/** Entrada de {@link buildNoMovementException}. */
691	export interface NoMovementExceptionInput {
692	  lojaId: number;
693	  lojaNome: string;
694	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
695	  lastMovementAt: Date | string | null;
696	  now: Date;
697	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
698	  hours?: TvBusinessHours;
699	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
700	  thresholdHours?: number;
701	}
