703	/**
704	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
705	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
706	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
707	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
708	 * Retorna null quando não há gap acima do threshold dentro da janela.
709	 */
710	export function buildNoMovementException(
711	  input: NoMovementExceptionInput,
712	): TvException | null {
713	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
714	  const gap = hoursWithoutMovementInWindow(
715	    input.lastMovementAt,
716	    input.now,
717	    input.hours ?? TV_BUSINESS_HOURS,
718	  );
719	  if (gap === null || gap <= threshold) return null;
720	  return {
721	    id: `no-movement:${input.lojaId}`,
722	    kind: 'no-movement',
723	    severity: 'amber',
724	    lojaId: input.lojaId,
725	    lojaNome: input.lojaNome,
726	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
727	  };
728	}
