730	// ─────────────────────────────────────────────────────────────────────────────
731	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
732	// ─────────────────────────────────────────────────────────────────────────────
733	
734	function trimOneDecimal(v: number): string {
735	  const rounded = Math.round(v * 10) / 10;
736	  return rounded.toLocaleString('pt-BR', {
737	    minimumFractionDigits: 0,
738	    maximumFractionDigits: 1,
739	  });
740	}
741	
742	/**
743	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
744	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
745	 * Valores negativos preservam o sinal ("-R$ 1,2k").
746	 */
747	export function formatCompactBRL(value: number): string {
748	  const sign = value < 0 ? '-' : '';
749	  const abs = Math.abs(value);
750	  // Bump pra M quando o arredondamento em k chegaria a 1000k
751	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
752	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
753	  }
754	  if (abs >= 1_000) {
755	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
756	  }
757	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
758	}
