760	// ─────────────────────────────────────────────────────────────────────────────
761	// Staleness
762	// ─────────────────────────────────────────────────────────────────────────────
763	
764	/**
765	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
766	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
767	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
768	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
769	 */
770	export function classifyStaleness(
771	  lastUpdatedAt: Date | string | number | null | undefined,
772	  expectedIntervalMs: number,
773	  now: Date,
774	): TvFreshnessLevel {
775	  if (lastUpdatedAt == null) return 'very-stale';
776	  const ts = new Date(lastUpdatedAt).getTime();
777	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
778	  const age = now.getTime() - ts;
779	  if (age < 2 * expectedIntervalMs) return 'fresh';
780	  if (age < 6 * expectedIntervalMs) return 'stale';
781	  return 'very-stale';
782	}
783	
784	/**
785	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
786	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
787	 *
788	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
789	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
790	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
791	 * parar de avançar além de 2× o intervalo esperado.
792	 */
793	export function buildFreshness(
794	  liveUpdatedAtMs: number,
795	  stockUpdatedAtMs: number,
796	  intervals: { liveMs: number; slowMs: number },
797	  now: Date,
798	): TvFreshness {
799	  const liveUpdatedAt =
800	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
801	  const stockUpdatedAt =
802	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
803	  return {
804	    vendasLive: {
805	      updatedAt: liveUpdatedAt,
806	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
807	      expectedIntervalMs: intervals.liveMs,
808	    },
809	    estoque: {
810	      updatedAt: stockUpdatedAt,
811	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
812	      expectedIntervalMs: intervals.slowMs,
813	    },
814	    geradoEm: now.toISOString(),
815	  };
816	}
