818	// ─────────────────────────────────────────────────────────────────────────────
819	// Exceções — ordenação e corte
820	// ─────────────────────────────────────────────────────────────────────────────
821	
822	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
823	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
824	const KIND_ORDER: Record<string, number> = {
825	  'stock-out': 0,
826	  'stock-low': 1,
827	  'no-movement': 2,
828	  'stale-data': 3,
829	};
830	
831	/**
832	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
833	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
834	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
835	 * contagem do excedente.
836	 */
837	export function sortAndLimitExceptions(
838	  exceptions: TvException[],
839	  limit: number = TV_EXCEPTIONS_LIMIT,
840	): TvExceptionsResult {
841	  const sorted = [...exceptions].sort((a, b) => {
842	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
843	    if (sev !== 0) return sev;
844	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
845	    if (kind !== 0) return kind;
846	    return a.message.localeCompare(b.message, 'pt-BR');
847	  });
848	  return {
849	    items: sorted.slice(0, limit),
850	    overflowCount: Math.max(0, sorted.length - limit),
851	    totalCount: sorted.length,
852	  };
853	}
