859	/** Linha mínima de `movimentacoes` necessária à agregação. */
860	export interface MovementRow {
861	  loja_id: number | null;
862	  tipo_movimentacao: string;
863	  data_movimentacao: string | null;
864	}
865	
866	/** Resultado por loja da agregação de movimentações do dia. */
867	export interface MovementAggregate {
868	  entradas: number;
869	  saidas: number;
870	  ultimaBipagem: string | null;
871	}
872	
873	/**
874	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
875	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
876	 * são ignoradas.
877	 */
878	export function aggregateMovements(
879	  rows: MovementRow[],
880	): Map<number, MovementAggregate> {
881	  const out = new Map<number, MovementAggregate>();
882	  for (const row of rows) {
883	    if (row.loja_id == null) continue;
884	    let agg = out.get(row.loja_id);
885	    if (!agg) {
886	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
887	      out.set(row.loja_id, agg);
888	    }
889	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
890	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
891	    if (
892	      row.data_movimentacao &&
893	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
894	    ) {
895	      agg.ultimaBipagem = row.data_movimentacao;
896	    }
897	  }
898	  return out;
899	}
