915	/**
916	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
917	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
918	 */
919	export function isTvAlertSetor(setor: string | null | undefined): boolean {
920	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
921	}
