923	/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
924	export interface StockRow {
925	  loja_id: number | null;
926	  quantidade_atual: number | null;
927	  quantidade_minima: number | null;
928	  produtoNome: string;
929	  /** `produtos_master.setor` cru (caixa/acentos inconsistentes no banco). */
930	  setor: string | null;
931	}
