977	/**
978	 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
979	 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
980	 */
981	export function buildStockExceptions(
982	  detailByLoja: Map<number, StockDetail>,
983	  lojaNomeById: Map<number, string>,
984	): TvException[] {
985	  const out: TvException[] = [];
986	  for (const [lojaId, detail] of detailByLoja) {
987	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
988	    for (const item of detail.itens) {
989	      out.push({
990	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
991	        kind: item.zerado ? 'stock-out' : 'stock-low',
992	        severity: item.zerado ? 'red' : 'amber',
993	        lojaId,
994	        lojaNome,
995	        message: item.zerado
996	          ? `${item.produtoNome} zerado — ${lojaNome}`
997	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
998	        produtoNome: item.produtoNome,
999	        quantidade: item.quantidade,
1000	        quantidadeMinima: item.quantidadeMinima,
1001	      });
1002	    }
1003	  }
1004	  return out;
1005	}
