1051	/**
1052	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1053	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1054	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1055	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1056	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1057	 * o drill-down, a lista completa.
1058	 */
1059	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1060	  const missingFraction = (c: TvCriticalItem): number =>
1061	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1062	  return items
1063	    .map<TvCriticalItem>((i) => ({
1064	      nome: i.produtoNome,
1065	      quantidade: i.quantidade,
1066	      minima: i.quantidadeMinima,
1067	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1068	    }))
1069	    .sort((a, b) => {
1070	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1071	      const diff = missingFraction(b) - missingFraction(a);
1072	      if (diff !== 0) return diff;
1073	      return a.nome.localeCompare(b.nome, 'pt-BR');
1074	    });
1075	}
