1096	/**
1097	 * Agrega perdas do período: R$ (soma de `valor_estimado`, nulls contam 0 —
1098	 * a perda EXISTE mesmo sem valor estimado e entra na contagem de itens) e
1099	 * nº de registros, por loja e total da rede. Linhas sem loja_id entram
1100	 * SOMENTE no total (não há coluna para atribuí-las).
1101	 */
1102	export function aggregatePerdas(rows: PerdaAggRow[]): PerdasByLoja {
1103	  const byLoja = new Map<number, PerdasAggregate>();
1104	  const total: PerdasAggregate = { valor: 0, itens: 0 };
1105	  for (const row of rows) {
1106	    const valor = row.valor_estimado ?? 0;
1107	    total.valor += valor;
1108	    total.itens += 1;
1109	    if (row.loja_id == null) continue;
1110	    let agg = byLoja.get(row.loja_id);
1111	    if (!agg) {
1112	      agg = { valor: 0, itens: 0 };
1113	      byLoja.set(row.loja_id, agg);
1114	    }
1115	    agg.valor += valor;
1116	    agg.itens += 1;
1117	  }
1118	  return { byLoja, total };
1119	}
