151	/** Strip do mês (R3+R4): MTD, meta mensal, meta da semana e projeção. */
152	function TvHeroMonthStrip({
153	  monthProgress,
154	  now,
155	}: {
156	  monthProgress: TvMonthProgress;
157	  now: Date;
158	}) {
159	  const { mtdTotal, metaMensal, pctMeta, currentWeek, projection } =
160	    monthProgress;
161	
162	  // % do mês decorrido (tick de "esperado agora" da barra mensal)
163	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
164	  const expectedMonthPct = Math.round((now.getDate() / daysInMonth) * 100);
165	  const monthRatio =
166	    pctMeta != null && expectedMonthPct > 0 ? pctMeta / expectedMonthPct : null;
167	  const monthBarColor = metaBarColorFromRatio(monthRatio, now);
168	
169	  // Meta da semana corrente (target redistribuído × realizado)
170	  const weekPct =
171	    currentWeek && currentWeek.target > 0
172	      ? ((currentWeek.achieved ?? 0) / currentWeek.target) * 100
173	      : null;
174	  const weekColor = metaBarColorFromRatio(
175	    weekPct != null ? weekPct / 100 : null,
176	    now,
177	  );
178	
179	  const labelCls =
180	    'font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]';
181	  const valueCls =
182	    'mt-1 font-momma text-[clamp(1.25rem,1.8vw,3.25rem)] font-bold leading-none text-[#2D362E] tabular-nums';
183	
184	  return (
185	    <div
186	      className="grid grid-cols-2 items-start gap-x-4 gap-y-4 border-t border-[#57715B]/10 pt-4 lg:grid-cols-4 lg:gap-8"
187	      data-testid="tv-hero-month-strip"
188	    >
189	      {/* Mês até agora (MTD da rede) */}
190	      <div className="min-w-0">
191	        <span className={labelCls}>MÊS ATÉ AGORA</span>
192	        <p className={valueCls} data-testid="tv-hero-mtd">
193	          {formatCompactBRL(mtdTotal)}
194	        </p>
195	      </div>
196	
197	      {/* % da meta mensal + mini barra (oculto sem meta cadastrada) */}
198	      {metaMensal != null && pctMeta != null ? (
199	        <div className="min-w-0" data-testid="tv-hero-month-goal">
200	          <span className={labelCls}>META MENSAL</span>
201	          <p className={valueCls}>
202	            {Math.round(pctMeta)}%
203	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
204	              {' '}
205	              de {formatCompactBRL(metaMensal)}
206	            </span>
207	          </p>
208	          <div className="mt-2 max-w-[18rem]">
209	            <TvMetaBar
210	              fillPct={pctMeta}
211	              expectedPct={expectedMonthPct}
212	              color={monthBarColor}
213	              size="card"
214	            />
215	          </div>
216	        </div>
217	      ) : (
218	        <div className="min-w-0" aria-hidden />
219	      )}
220	
221	      {/* Meta da semana corrente (redistribuída — R4) */}
222	      {currentWeek && (
223	        <div className="min-w-0" data-testid="tv-hero-week-goal">
224	          <span className={labelCls}>META DA SEMANA</span>
225	          <p className={valueCls}>
226	            {formatCompactBRL(currentWeek.achieved ?? 0)}
227	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
228	              {' '}
229	              / {formatCompactBRL(currentWeek.target)}
230	            </span>
231	          </p>
232	          {weekPct != null && (
233	            <p
234	              className={`mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold tabular-nums ${WEEK_PCT_TEXT_CLS[weekColor]}`}
235	            >
236	              {Math.round(weekPct)}% da semana
237	            </p>
238	          )}
239	        </div>
240	      )}
241	
242	      {/* Projeção de fim de mês (run-rate — R3) */}
243	      <div className="min-w-0">
244	        <span className={labelCls}>PROJEÇÃO DO MÊS</span>
245	        <p className={valueCls} data-testid="tv-hero-projection">
246	          {formatCompactBRL(projection)}
247	        </p>
248	      </div>
249	    </div>
250	  );
251	}
