26	} from '../model/types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Live indicator — dot compacto substituindo o chip "ao vivo" (texto ruim)
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Indicador de frescor minimalista: dot animado (live) ou dot estático
34	 * (stale/lagged). Usa cor + forma, não texto — compatível com WCAG 1.4.1
35	 * porque é sempre acompanhado do horário de atualização no mesmo elemento.
36	 */
37	export function TvLiveIndicator({
38	  channel,
39	  liveLevel,
