67	import { formatLaggedDateLabel } from '../model/tvMath';
68	import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';
69	
70	// ─────────────────────────────────────────────────────────────────────────────
71	// Delta comparativo (v3: principal = vs ONTEM; rótulo da base é genérico)
72	// ─────────────────────────────────────────────────────────────────────────────
73	
74	interface TvDeltaChipProps {
75	  /** Delta % vs a base comparada. */
76	  delta: number;
77	  /** Rótulo da base comparada ("ontem", "dia ant.", "qua."). */
78	  label: string;
