80	  size: 'hero' | 'card';
81	}
82	
83	/**
84	 * Chip de delta comparativo. Neutro (pill sage suave) sempre — exceto delta
85	 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
86	 */
87	export function TvDeltaChip({ delta, label, size }: TvDeltaChipProps) {
88	  const isAlert = delta <= -15;
89	  const colorCls = isAlert
90	    ? 'bg-amber-50 text-amber-600'
91	    : 'bg-[#57715B]/8 text-[#5F6F63]';
92	  const textCls =
93	    size === 'hero'
94	      ? 'text-[clamp(0.875rem,1.45vw,2.625rem)]'
95	      : 'text-[clamp(0.8125rem,1.25vw,2.25rem)]';
96	  const Icon = delta < 0 ? ArrowDown : ArrowUp;
97	  return (
98	    <span
99	      className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 font-momma font-medium tabular-nums leading-none lg:px-4 lg:py-1.5 ${textCls} ${colorCls}`}
