108	// ─────────────────────────────────────────────────────────────────────────────
109	// Chip de fonte (freshness honesta — design.md §4 item 1)
110	// ─────────────────────────────────────────────────────────────────────────────
111	
112	interface TvSourceChipProps {
113	  channel: TvSalesChannel;
114	  /** Freshness da fonte live (ignorado para canal Linx). */
115	  liveLevel: TvFreshnessLevel;
116	  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
117	  laggedDate?: string | null;
