119	
120	/**
121	 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
122	 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
123	 * (defasagem esperada não é alarme).
124	 */
125	export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
126	  if (channel === 'linx-lagged') {
127	    return (
128	      <span
129	        className="inline-flex items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-[#5F6F63]"
