137	  if (liveLevel === 'fresh') {
138	    return (
139	      <span
140	        className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-emerald-600"
141	        data-testid="tv-source-chip-live"
