148	  return (
149	    <span
150	      className="inline-flex items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600"
151	      data-testid="tv-source-chip-stale"
152	    >
153	      <RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
154	      atrasado
155	    </span>
156	  );
