158	
159	// ─────────────────────────────────────────────────────────────────────────────
160	// Chip de estado RAG (redundância não-cromática lível a 3m)
161	// ─────────────────────────────────────────────────────────────────────────────
162	
163	/**
164	 * Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok.
165	 * Tem variantes dark (badge do design system) porque também é usado no
166	 * drill-down `/tv/loja/:id`, que roda DENTRO do DashboardLayout (tema livre).
167	 */
168	export function TvStateChip({ rag }: { rag: TvRagStatus }) {
