170	  if (rag === 'red') {
171	    return (
172	      <span
173	        className="inline-flex items-center gap-1 rounded-full bg-red-50 px-2 py-0.5 text-xs font-semibold leading-none text-red-600 dark:bg-red-900/20"
174	        data-testid="tv-state-chip-red"
