176	        <OctagonAlert className="h-3 w-3 shrink-0" aria-hidden />
177	        crítico
178	      </span>
179	    );
180	  }
181	  return (
182	    <span
183	      className="inline-flex items-center gap-1 rounded-full bg-amber-50 px-2 py-0.5 text-xs font-semibold leading-none text-amber-600 dark:bg-amber-900/20"
184	      data-testid="tv-state-chip-amber"
185	    >
186	      <TriangleAlert className="h-3 w-3 shrink-0" aria-hidden />
187	      atenção
188	    </span>
189	  );
