191	
192	// ─────────────────────────────────────────────────────────────────────────────
193	// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
194	// ─────────────────────────────────────────────────────────────────────────────
195	
196	/**
197	 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
198	 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
199	 */
200	export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
201	  const total = estoque.zerados + estoque.abaixoMinimo;
202	  if (total === 0) return null;
203	  if (estoque.zerados > 0) {
204	    return (
205	      <span
206	        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600 tabular-nums"
207	        data-testid="tv-stock-badge-red"
208	      >
209	        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
210	        {total}
211	      </span>
212	    );
213	  }
214	  return (
215	    <span
216	      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600 tabular-nums"
217	      data-testid="tv-stock-badge-amber"
218	    >
