224	
225	// ─────────────────────────────────────────────────────────────────────────────
226	// Chip de ranking (1ª / 2ª / 3ª loja por venda) — apenas period "today"
227	// ─────────────────────────────────────────────────────────────────────────────
228	
229	interface TvRankChipProps {
230	  /** Posição de 1 a 3 (valores maiores não geram chip). */
231	  rank: 1 | 2 | 3;
232	}
233	
234	/**
235	 * Badge compacto de ranking da loja por venda do dia (top-3).
236	 * Dourado para 1ª; sage suave para 2ª e 3ª (hierarquia visual sem excesso).
237	 */
238	export function TvRankChip({ rank }: TvRankChipProps) {
239	  const isGold = rank === 1;
240	  const label = rank === 1 ? '🥇 1ª' : rank === 2 ? '2ª' : '3ª';
241	  return (
242	    <span
243	      className={`inline-flex items-center rounded-full px-2.5 py-0.5 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold leading-none tabular-nums ${
244	        isGold
245	          ? 'bg-[#C5A065]/10 text-[#C5A065]'
246	          : 'bg-[#57715B]/8 text-[#7C887E]'
247	      }`}
248	      data-testid={`tv-rank-chip-${rank}`}
249	      aria-label={`${rank}ª colocada`}
250	    >
251	      {label}
252	    </span>
253	  );
254	}
255	
256	// ─────────────────────────────────────────────────────────────────────────────
257	// Barra de % meta com tick de "esperado agora"
258	// ─────────────────────────────────────────────────────────────────────────────
259	
260	const BAR_FILL_CLS: Record<TvBarColor, string> = {
261	  sage: 'bg-gradient-to-r from-[#57715B] to-[#4a6250]',
262	  amber: 'bg-gradient-to-r from-amber-400 to-amber-500',
263	  red: 'bg-gradient-to-r from-red-400 to-red-500',
264	};
265	
266	interface TvMetaBarProps {
267	  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
268	  fillPct: number | null;
269	  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
270	  expectedPct: number | null;
271	  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
272	  color: TvBarColor;
273	  /**
274	   * Altura da barra: hero 14→20px, card 10→12px, mini 4→6px (mobile → lg+).
275	   * `mini` é a variante SECUNDÁRIA (ex.: meta semanal na coluna de loja) —
276	   * mais fina que a barra diária para não competir na hierarquia visual.
277	   */
278	  size: 'hero' | 'card' | 'mini';
279	}
280	
281	/**
282	 * Barra horizontal de % meta: trilha sage suave (`#57715B/10`),
283	 * preenchimento em gradiente por estado de venda e tick DOURADO de
284	 * "esperado agora" (pró-rata). Transição de width 600ms ease-out (§8.1.3).
285	 */
286	export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
287	  const heightCls =
288	    size === 'hero' ? 'h-3.5 lg:h-5' : size === 'card' ? 'h-2.5 lg:h-3' : 'h-1 lg:h-1.5';
289	  const tick =
290	    size === 'hero'
291	      ? { width: 3, height: 28, offset: -4 }
292	      : size === 'card'
293	        ? { width: 2, height: 20, offset: -4 }
294	        : { width: 2, height: 12, offset: -3 };
295	  return (
296	    <div
297	      className={`relative w-full rounded-full bg-[#57715B]/10 ${heightCls}`}
298	      data-testid="tv-meta-bar"
299	    >
300	      {fillPct != null && (
301	        <div
302	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
303	          style={{ width: `${clampPct(fillPct)}%` }}
304	          data-testid="tv-meta-bar-fill"
305	        />
306	      )}
307	      {expectedPct != null && (
308	        <div
309	          className="absolute rounded-full bg-[#C5A065]"
310	          style={{
311	            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
312	            top: tick.offset,
313	            width: tick.width,
314	            height: tick.height,
315	          }}
316	          data-testid="tv-meta-bar-tick"
317	        />
318	      )}
319	    </div>
320	  );
321	}
