1	/**
2	 * @module features/tv-dashboard/ui/TvMetas.page
3	 *
4	 * Página `/tv/metas` (admin): grade lojas × dias da semana (dom–sáb) para
5	 * cadastrar a meta diária de vendas em R$ (`metas_vendas`, upsert por
6	 * loja_id+dia_semana). Usa o layout normal do app — o DashboardLayout é
7	 * aplicado na rota (App.tsx), como nas demais páginas.
8	 */
9	
10	import { useEffect, useMemo, useRef, useState } from 'react';
11	import { useNavigate } from 'react-router-dom';
12	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
13	import { ArrowLeft, ChevronDown, MonitorPlay, Save } from 'lucide-react';
14	import { toast } from 'sonner';
15	import { supabase } from '@/integrations/supabase/client';
16	import { Button } from '@/shared/ui/button';
17	import { GlassCard } from '@/shared/ui/glass-card';
18	import { Input } from '@/shared/ui/input';
19	import {
20	  Table,
21	  TableBody,
22	  TableCell,
23	  TableHead,
24	  TableHeader,
25	  TableRow,
26	} from '@/shared/ui/table';
27	import { tvDashboardKeys } from '../model/useTvDashboardData';
28	
29	/** Cabeçalhos das colunas (índice = `Date.getDay()`: 0=domingo). */
30	const WEEKDAYS = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'] as const;
31	
32	/** Nomes pt-BR dos meses (índice = `mes − 1`, convenção 1-12 da tabela). */
33	const MONTH_NAMES = [
34	  'Janeiro',
35	  'Fevereiro',
36	  'Março',
37	  'Abril',
38	  'Maio',
39	  'Junho',
40	  'Julho',
41	  'Agosto',
42	  'Setembro',
43	  'Outubro',
44	  'Novembro',
45	  'Dezembro',
46	] as const;
47	
48	interface MetasLoja {
49	  id: number;
50	  nome: string;
51	}
52	
53	interface MetaRow {
54	  loja_id: number;
55	  dia_semana: number;
56	  valor_meta: number;
57	}
58	
59	function cellKey(lojaId: number, dia: number): string {
60	  return `${lojaId}:${dia}`;
61	}
62	
63	function isFactoryTipo(tipo: string | null): boolean {
64	  const t = (tipo ?? '').toLowerCase();
65	  return t.startsWith('fabrica') || t.startsWith('fábrica');
66	}
67	
68	async function fetchLojasVenda(): Promise<MetasLoja[]> {
69	  const { data, error } = await supabase
70	    .from('lojas')
71	    .select('id, nome, tipo')
72	    .eq('ativo', true)
73	    .order('id');
74	  if (error) throw error;
75	  return (data ?? [])
76	    .filter((l) => !isFactoryTipo(l.tipo))
77	    .map((l) => ({ id: l.id, nome: l.nome }));
78	}
79	
80	async function fetchMetas(): Promise<MetaRow[]> {
81	  const { data, error } = await supabase
82	    .from('metas_vendas')
83	    .select('loja_id, dia_semana, valor_meta')
84	    .limit(1000);
85	  if (error) throw error;
86	  return data ?? [];
87	}
88	
89	/** Linha de `metas_mensais` de um mês (loja_id NULL = meta da rede). */
90	interface MetaMensalRow {
91	  id: string;
92	  loja_id: number | null;
93	  valor_meta: number;
94	}
95	
96	async function fetchMetasMensais(ano: number, mes: number): Promise<MetaMensalRow[]> {
97	  const { data, error } = await supabase
98	    .from('metas_mensais')
99	    .select('id, loja_id, valor_meta')
100	    .eq('ano', ano)
101	    .eq('mes', mes);
102	  if (error) throw error;
103	  return data ?? [];
104	}
105	
106	/** Parse de input de meta: vazio/inválido → null; aceita vírgula decimal. */
107	function parseMetaInput(raw: string): number | null {
108	  if (raw.trim() === '') return null;
109	  const parsed = Number(raw.replace(',', '.'));
110	  if (!Number.isFinite(parsed) || parsed < 0) return null;
111	  return parsed;
112	}
113	
114	/** Grade de metas do Painel TV (admin only — rota protegida em App.tsx). */
115	export default function TvMetasPage() {
116	  const navigate = useNavigate();
117	  const queryClient = useQueryClient();
118	
119	  const lojasQuery = useQuery({ queryKey: ['tv-metas', 'lojas'], queryFn: fetchLojasVenda });
120	  const metasQuery = useQuery({ queryKey: ['tv-metas', 'valores'], queryFn: fetchMetas });
121	
122	  // ── Meta mensal (R4): mês/ano selecionável, rede + por loja ──
123	  const [mensalAno, setMensalAno] = useState(() => new Date().getFullYear());
124	  const [mensalMes, setMensalMes] = useState(() => new Date().getMonth() + 1);
125	  const [showMetasPorLoja, setShowMetasPorLoja] = useState(false);
126	  const mensaisQuery = useQuery({
127	    queryKey: ['tv-metas', 'mensais', mensalAno, mensalMes],
128	    queryFn: () => fetchMetasMensais(mensalAno, mensalMes),
129	  });
130	
131	  const [redeValue, setRedeValue] = useState('');
132	  const [lojaMensalValues, setLojaMensalValues] = useState<Record<number, string>>({});
133	  // Re-inicializa quando o mês selecionado (re)carrega do banco
134	  useEffect(() => {
135	    const rows = mensaisQuery.data;
136	    if (!rows) return;
137	    const rede = rows.find((r) => r.loja_id === null);
